const S=0.7071068;
const DIRS={up:[1,0],down:[-1,0],left:[0,-1],right:[0,1]};
const Q={up:[-S,0,0,S],down:[S,0,0,S],left:[0,0,S,S],right:[0,0,-S,S]};
function pos(r,c){return[(c-1)*1.1,(r==2&&c==2)?0.46:0.4,(1-r)*1.1];}
function dist(s){return(2-s.r)+(2-s.c);}
function hintDir(s){return s.c<2?'right':'up';}
export function initialState(){return{r:0,c:0,moves:0,hint:false,msg:''};}
export function reduce({state,event}){
if(event.type!=='action')return state;
const a=event.action;const won=dist(state)===0;
if(won)return{...state,msg:'You already reached the goal. Press Reset to play again.'};
if(a==='hint')return{...state,hint:true,msg:'Hint: move '+hintDir(state)+' to get one step closer.'};
const d=DIRS[a];if(!d)return state;
const r=state.r+d[0],c=state.c+d[1];
if(r<0||r>2||c<0||c>2)return{...state,hint:false,msg:'Can\'t move '+a+': that would leave the board.'};
return{r,c,moves:state.moves+1,hint:false,msg:''};}
export function evaluate({state}){
const s=state||initialState();const p=pos(s.r,s.c);const d=dist(s);
const nodes={tokenBall:{position:p}};
if(s.hint&&d>0){const h=hintDir(s);const v=DIRS[h];nodes.hintArrow={visible:true,position:[p[0]+v[1]*0.32,0.4,p[2]-v[0]*0.32],quaternion:Q[h]};}else nodes.hintArrow={visible:false};
let goal;
if(d===0)goal={status:'won',message:'Goal reached in '+s.moves+' moves. The shortest route is 4 moves'+(s.moves===4?' - perfect!':'.')};
else goal={status:'playing',message:s.msg||('Reach the goal: '+d+' step'+(d===1?'':'s')+' away.')};
return{nodes,readouts:{stepsLeft:d,moves:s.moves},goal};}
